-compile({nowarn_unused_function,e_type_double/3}).
e_type_double(V, Bin, _) when is_number(V) -> <<Bin/binary, V:64/little-float>>;
e_type_double(infinity, Bin, _) -> <<Bin/binary, 0:48, 240, 127>>;
e_type_double('-infinity', Bin, _) -> <<Bin/binary, 0:48, 240, 255>>;
e_type_double(nan, Bin, _) -> <<Bin/binary, 0:48, 248, 127>>.

-compile({nowarn_unused_function,e_unknown_elems/2}).
e_unknown_elems([Elem | Rest], Bin) ->
    BinR = case Elem of
               {varint, FNum, N} ->
                   BinF = e_varint(FNum bsl 3, Bin),
                   e_varint(N, BinF);
               {length_delimited, FNum, Data} ->
                   BinF = e_varint(FNum bsl 3 bor 2, Bin),
                   BinL = e_varint(byte_size(Data), BinF),
                   <<BinL/binary, Data/binary>>;
               {group, FNum, GroupFields} ->
                   Bin1 = e_varint(FNum bsl 3 bor 3, Bin),
                   Bin2 = e_unknown_elems(GroupFields, Bin1),
                   e_varint(FNum bsl 3 bor 4, Bin2);
               {fixed32, FNum, V} ->
                   BinF = e_varint(FNum bsl 3 bor 5, Bin),
                   <<BinF/binary, V:32/little>>;
               {fixed64, FNum, V} ->
                   BinF = e_varint(FNum bsl 3 bor 1, Bin),
                   <<BinF/binary, V:64/little>>
           end,
    e_unknown_elems(Rest, BinR);
e_unknown_elems([], Bin) -> Bin.

-compile({nowarn_unused_function,e_varint/3}).
e_varint(N, Bin, _TrUserData) -> e_varint(N, Bin).

-compile({nowarn_unused_function,e_varint/2}).
e_varint(N, Bin) when N =< 127 -> <<Bin/binary, N>>;
e_varint(N, Bin) ->
    Bin2 = <<Bin/binary, (N band 127 bor 128)>>,
    e_varint(N bsr 7, Bin2).

is_empty_string("") -> true;
is_empty_string(<<>>) -> true;
is_empty_string(L) when is_list(L) -> not string_has_chars(L);
is_empty_string(B) when is_binary(B) -> false.

string_has_chars([C | _]) when is_integer(C) -> true;
string_has_chars([H | T]) ->
    case string_has_chars(H) of
        true -> true;
        false -> string_has_chars(T)
    end;
string_has_chars(B) when is_binary(B), byte_size(B) =/= 0 -> true;
string_has_chars(C) when is_integer(C) -> true;
string_has_chars(<<>>) -> false;
string_has_chars([]) -> false.


decode_msg(Bin, MsgName) when is_binary(Bin) -> decode_msg(Bin, MsgName, []).

decode_msg(Bin, MsgName, Opts) when is_binary(Bin) ->
    TrUserData = proplists:get_value(user_data, Opts),
    decode_msg_1_catch(Bin, MsgName, TrUserData).

-ifdef('OTP_RELEASE').
decode_msg_1_catch(Bin, MsgName, TrUserData) ->
    try decode_msg_2_doit(MsgName, Bin, TrUserData)
    catch
        error:{gpb_error,_}=Reason:StackTrace ->
            erlang:raise(error, Reason, StackTrace);
        Class:Reason:StackTrace -> error({gpb_error,{decoding_failure, {Bin, MsgName, {Class, Reason, StackTrace}}}})
    end.
-else.
decode_msg_1_catch(Bin, MsgName, TrUserData) ->
    try decode_msg_2_doit(MsgName, Bin, TrUserData)
    catch
        error:{gpb_error,_}=Reason ->
            erlang:raise(error, Reason,
                         erlang:get_stacktrace());
        Class:Reason ->
            StackTrace = erlang:get_stacktrace(),
            error({gpb_error,{decoding_failure, {Bin, MsgName, {Class, Reason, StackTrace}}}})
    end.
-endif.

decode_msg_2_doit(health_check_request, Bin, TrUserData) -> id(decode_msg_health_check_request(Bin, TrUserData), TrUserData);
decode_msg_2_doit(health_request, Bin, TrUserData) -> id(decode_msg_health_request(Bin, TrUserData), TrUserData);
decode_msg_2_doit(cluster_check_request, Bin, TrUserData) -> id(decode_msg_cluster_check_request(Bin, TrUserData), TrUserData);
decode_msg_2_doit(memory_level_request, Bin, TrUserData) -> id(decode_msg_memory_level_request(Bin, TrUserData), TrUserData);
decode_msg_2_doit(memory_stats_request, Bin, TrUserData) -> id(decode_msg_memory_stats_request(Bin, TrUserData), TrUserData);
decode_msg_2_doit(health_check_response, Bin, TrUserData) -> id(decode_msg_health_check_response(Bin, TrUserData), TrUserData);
decode_msg_2_doit(health_response, Bin, TrUserData) -> id(decode_msg_health_response(Bin, TrUserData), TrUserData);
decode_msg_2_doit(cluster_check_response, Bin, TrUserData) -> id(decode_msg_cluster_check_response(Bin, TrUserData), TrUserData);
decode_msg_2_doit(memory_level_response, Bin, TrUserData) -> id(decode_msg_memory_level_response(Bin, TrUserData), TrUserData);
decode_msg_2_doit(memory_stats_response, Bin, TrUserData) -> id(decode_msg_memory_stats_response(Bin, TrUserData), TrUserData).



decode_msg_health_check_request(Bin, TrUserData) -> dfp_read_field_def_health_check_request(Bin, 0, 0, 0, id(<<>>, TrUserData), TrUserData).

dfp_read_field_def_health_check_request(<<10, Rest/binary>>, Z1, Z2, F, F@_1, TrUserData) -> d_field_health_check_request_store_id(Rest, Z1, Z2, F, F@_1, TrUserData);
dfp_read_field_def_health_check_request(<<>>, 0, 0, _, F@_1, _) -> #{store_id => F@_1};
dfp_read_field_def_health_check_request(Other, Z1, Z2, F, F@_1, TrUserData) -> dg_read_field_def_health_check_request(Other, Z1, Z2, F, F@_1, TrUserData).

dg_read_field_def_health_check_request(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData) when N < 32 - 7 -> dg_read_field_def_health_check_request(Rest, N + 7, X bsl N + Acc, F, F@_1, TrUserData);
dg_read_field_def_health_check_request(<<0:1, X:7, Rest/binary>>, N, Acc, _, F@_1, TrUserData) ->
    Key = X bsl N + Acc,
    case Key of
        10 -> d_field_health_check_request_store_id(Rest, 0, 0, 0, F@_1, TrUserData);
        _ ->
            case Key band 7 of
                0 -> skip_varint_health_check_request(Rest, 0, 0, Key bsr 3, F@_1, TrUserData);
                1 -> skip_64_health_check_request(Rest, 0, 0, Key bsr 3, F@_1, TrUserData);
                2 -> skip_length_delimited_health_check_request(Rest, 0, 0, Key bsr 3, F@_1, TrUserData);
                3 -> skip_group_health_check_request(Rest, 0, 0, Key bsr 3, F@_1, TrUserData);
                5 -> skip_32_health_check_request(Rest, 0, 0, Key bsr 3, F@_1, TrUserData)
            end
    end;
dg_read_field_def_health_check_request(<<>>, 0, 0, _, F@_1, _) -> #{store_id => F@_1}.

d_field_health_check_request_store_id(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData) when N < 57 -> d_field_health_check_request_store_id(Rest, N + 7, X bsl N + Acc, F, F@_1, TrUserData);
d_field_health_check_request_store_id(<<0:1, X:7, Rest/binary>>, N, Acc, F, _, TrUserData) ->
    {NewFValue, RestF} = begin Len = X bsl N + Acc, <<Bytes:Len/binary, Rest2/binary>> = Rest, Bytes2 = binary:copy(Bytes), {id(Bytes2, TrUserData), Rest2} end,
    dfp_read_field_def_health_check_request(RestF, 0, 0, F, NewFValue, TrUserData).

skip_varint_health_check_request(<<1:1, _:7, Rest/binary>>, Z1, Z2, F, F@_1, TrUserData) -> skip_varint_health_check_request(Rest, Z1, Z2, F, F@_1, TrUserData);
skip_varint_health_check_request(<<0:1, _:7, Rest/binary>>, Z1, Z2, F, F@_1, TrUserData) -> dfp_read_field_def_health_check_request(Rest, Z1, Z2, F, F@_1, TrUserData).

skip_length_delimited_health_check_request(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData) when N < 57 -> skip_length_delimited_health_check_request(Rest, N + 7, X bsl N + Acc, F, F@_1, TrUserData);
skip_length_delimited_health_check_request(<<0:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData) ->
    Length = X bsl N + Acc,
    <<_:Length/binary, Rest2/binary>> = Rest,
    dfp_read_field_def_health_check_request(Rest2, 0, 0, F, F@_1, TrUserData).

skip_group_health_check_request(Bin, _, Z2, FNum, F@_1, TrUserData) ->
    {_, Rest} = read_group(Bin, FNum),
    dfp_read_field_def_health_check_request(Rest, 0, Z2, FNum, F@_1, TrUserData).

