-compile({nowarn_unused_function,merge_msg_health_check_response/3}).
merge_msg_health_check_response(PMsg, NMsg, TrUserData) ->
    S1 = #{},
    S2 = case {PMsg, NMsg} of
             {_, #{status := NFstatus}} -> S1#{status => NFstatus};
             {#{status := PFstatus}, _} -> S1#{status => PFstatus};
             _ -> S1
         end,
    case {PMsg, NMsg} of
        {#{details := PFdetails}, #{details := NFdetails}} -> S2#{details => 'tr_merge_health_check_response.details'(PFdetails, NFdetails, TrUserData)};
        {_, #{details := NFdetails}} -> S2#{details => NFdetails};
        {#{details := PFdetails}, _} -> S2#{details => PFdetails};
        {_, _} -> S2
    end.

-compile({nowarn_unused_function,merge_msg_health_response/3}).
merge_msg_health_response(PMsg, NMsg, TrUserData) ->
    S1 = #{},
    S2 = case {PMsg, NMsg} of
             {_, #{status := NFstatus}} -> S1#{status => NFstatus};
             {#{status := PFstatus}, _} -> S1#{status => PFstatus};
             _ -> S1
         end,
    S3 = case {PMsg, NMsg} of
             {#{stores := PFstores}, #{stores := NFstores}} -> S2#{stores => 'tr_merge_health_response.stores'(PFstores, NFstores, TrUserData)};
             {_, #{stores := NFstores}} -> S2#{stores => NFstores};
             {#{stores := PFstores}, _} -> S2#{stores => PFstores};
             {_, _} -> S2
         end,
    S4 = case {PMsg, NMsg} of
             {_, #{total_workers := NFtotal_workers}} -> S3#{total_workers => NFtotal_workers};
             {#{total_workers := PFtotal_workers}, _} -> S3#{total_workers => PFtotal_workers};
             _ -> S3
         end,
    S5 = case {PMsg, NMsg} of
             {_, #{node := NFnode}} -> S4#{node => NFnode};
             {#{node := PFnode}, _} -> S4#{node => PFnode};
             _ -> S4
         end,
    case {PMsg, NMsg} of
        {_, #{timestamp := NFtimestamp}} -> S5#{timestamp => NFtimestamp};
        {#{timestamp := PFtimestamp}, _} -> S5#{timestamp => PFtimestamp};
        _ -> S5
    end.

