-compile({nowarn_unused_function,merge_msg_memory_stats_response/3}).
merge_msg_memory_stats_response(PMsg, NMsg, TrUserData) ->
    S1 = #{},
    S2 = case {PMsg, NMsg} of
             {_, #{used_bytes := NFused_bytes}} -> S1#{used_bytes => NFused_bytes};
             {#{used_bytes := PFused_bytes}, _} -> S1#{used_bytes => PFused_bytes};
             _ -> S1
         end,
    S3 = case {PMsg, NMsg} of
             {_, #{total_bytes := NFtotal_bytes}} -> S2#{total_bytes => NFtotal_bytes};
             {#{total_bytes := PFtotal_bytes}, _} -> S2#{total_bytes => PFtotal_bytes};
             _ -> S2
         end,
    S4 = case {PMsg, NMsg} of
             {_, #{usage_percent := NFusage_percent}} -> S3#{usage_percent => NFusage_percent};
             {#{usage_percent := PFusage_percent}, _} -> S3#{usage_percent => PFusage_percent};
             _ -> S3
         end,
