        memory_level_request -> v_msg_memory_level_request(Msg, [MsgName], TrUserData);
        memory_stats_request -> v_msg_memory_stats_request(Msg, [MsgName], TrUserData);
        health_check_response -> v_msg_health_check_response(Msg, [MsgName], TrUserData);
        health_response -> v_msg_health_response(Msg, [MsgName], TrUserData);
        cluster_check_response -> v_msg_cluster_check_response(Msg, [MsgName], TrUserData);
        memory_level_response -> v_msg_memory_level_response(Msg, [MsgName], TrUserData);
        memory_stats_response -> v_msg_memory_stats_response(Msg, [MsgName], TrUserData);
        _ -> mk_type_error(not_a_known_message, Msg, [])
    end.


